import{_ as e,c as r,o as t,a0 as i}from"./chunks/framework.DKRgXLPU.js";const _=JSON.parse('{"title":"Mentale spiløvelser","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/da/exercise-worksheets.md","filePath":"public/downloads/da/exercise-worksheets.md"}');const l=e({name:"public/downloads/da/exercise-worksheets.md"},[["render",function(e,_,l,n,a,s){return t(),r("div",null,[..._[0]||(_[0]=[i('<h1 id="mentale-spiløvelser" tabindex="-1">Mentale spiløvelser <a class="header-anchor" href="#mentale-spiløvelser" aria-label="Permalink to &quot;Mentale spiløvelser&quot;">​</a></h1><p><strong>Pétanque Academy - Praktiske øvelser</strong></p><hr><h2 id="øvelse-1-refleksion-af-strømningstilstand" tabindex="-1">Øvelse 1: Refleksion af strømningstilstand <a class="header-anchor" href="#øvelse-1-refleksion-af-strømningstilstand" aria-label="Permalink to &quot;Øvelse 1: Refleksion af strømningstilstand&quot;">​</a></h2><h3 id="hvornar-har-du-oplevet-flow" tabindex="-1">Hvornår har du oplevet flow? <a class="header-anchor" href="#hvornar-har-du-oplevet-flow" aria-label="Permalink to &quot;Hvornår har du oplevet flow?&quot;">​</a></h3><p>Tænk på en gang, hvor du spillede din bedste petanque:</p><p><strong>Beskriv situationen:</strong></p><ul><li>Hvilken turnering/kamp var det?</li><li>Hvad var betingelserne?</li><li>Hvem spillede du med?</li></ul><hr><hr><p><strong>Hvordan føltes det?</strong></p><ul><li>Hvad var din mentale tilstand?</li><li>Hvordan føltes tiden?</li><li>Hvad tænkte du (eller tænkte du ikke)?</li></ul><hr><hr><p><strong>Hvad hjalp dig med at nå dertil?</strong></p><ul><li>Hvad lavede du før kampen?</li><li>Hvad var anderledes ved den dag?</li><li>Kan du genskabe nogen af disse forhold?</li></ul><hr><hr><hr><h2 id="øvelse-2-indre-kritiker-opgørelse" tabindex="-1">Øvelse 2: Indre kritiker-opgørelse <a class="header-anchor" href="#øvelse-2-indre-kritiker-opgørelse" aria-label="Permalink to &quot;Øvelse 2: Indre kritiker-opgørelse&quot;">​</a></h2><h3 id="identificer-din-indre-kritiker" tabindex="-1">Identificér din indre kritiker <a class="header-anchor" href="#identificer-din-indre-kritiker" aria-label="Permalink to &quot;Identificér din indre kritiker&quot;">​</a></h3><p>Hvad siger din indre kritiker?</p><p>Nævn 3-5 almindelige kritiske tanker, du har under konkurrencer:</p><ol><li><hr></li><li><hr></li><li><hr></li><li><hr></li><li><hr></li></ol><p>Hvornår optræder den?</p><ul><li>Efter fejl? □</li><li>Før vigtige optagelser? □</li><li>Når man spiller mod stærke modstandere? □</li><li>Når holdkammerater ser på? □</li><li>Andet: _______________________________________________</li></ul><hr><h2 id="øvelse-3-øvelse-i-omformulering" tabindex="-1">Øvelse 3: Øvelse i omformulering <a class="header-anchor" href="#øvelse-3-øvelse-i-omformulering" aria-label="Permalink to &quot;Øvelse 3: Øvelse i omformulering&quot;">​</a></h2><h3 id="forvandl-kritiker-til-coach" tabindex="-1">Forvandl kritiker til coach <a class="header-anchor" href="#forvandl-kritiker-til-coach" aria-label="Permalink to &quot;Forvandl kritiker til coach&quot;">​</a></h3><p><strong>For hver Indre Kritiker-tanke, skriv en Indre Coach-omformulering:</strong></p><table tabindex="0"><thead><tr><th>Indre kritiker</th><th>Indre coach</th></tr></thead><tbody><tr><td>Eksempel: &quot;Jeg fejler altid under pres&quot;</td><td>&quot;Jeg har haft succes under pres før, jeg kan gøre det igen&quot;</td></tr><tr><td>1. ________________________</td><td>_________________________</td></tr><tr><td>2. _________________________</td><td>_________________________</td></tr><tr><td>3. ________________________</td><td>_________________________</td></tr></tbody></table><p><strong>Øv dig i at sige disse højt</strong></p><hr><h2 id="øvelse-4-design-af-rutine-før-optagelse" tabindex="-1">Øvelse 4: Design af rutine før optagelse <a class="header-anchor" href="#øvelse-4-design-af-rutine-før-optagelse" aria-label="Permalink to &quot;Øvelse 4: Design af rutine før optagelse&quot;">​</a></h2><h3 id="skab-din-personlige-rutine" tabindex="-1">Skab din personlige rutine <a class="header-anchor" href="#skab-din-personlige-rutine" aria-label="Permalink to &quot;Skab din personlige rutine&quot;">​</a></h3><p>Design en 4-trins rutine før indtagelse, der fungerer for dig:</p><p><strong>Trin 1: Visualiser</strong></p><ul><li>Hvad vil du præcist visualisere?</li><li>Hvor længe (2-3 sekunder)?</li></ul><hr><p><strong>Trin 2: Træk vejret</strong></p><ul><li>En dyb indånding eller tre?</li><li>Noget specifikt mønster?</li></ul><hr><p><strong>Trin 3: Anker</strong></p><ul><li>Hvilket fysisk anker vil du bruge?</li><li>Touch-boule? Specifik stilling?</li></ul><hr><p><strong>Trin 4: Udfør</strong></p><ul><li>Hvad er dit mentale signal?</li><li>&quot;Tillid&quot; / &quot;Flow&quot; / &quot;Go&quot;?</li></ul><hr><p><strong>Øv denne rutine 10 gange i dag</strong></p><hr><h2 id="øvelse-5-trykudløsere" tabindex="-1">Øvelse 5: Trykudløsere <a class="header-anchor" href="#øvelse-5-trykudløsere" aria-label="Permalink to &quot;Øvelse 5: Trykudløsere&quot;">​</a></h2><h3 id="identificer-dine-trykpunkter" tabindex="-1">Identificér dine trykpunkter <a class="header-anchor" href="#identificer-dine-trykpunkter" aria-label="Permalink to &quot;Identificér dine trykpunkter&quot;">​</a></h3><p>Hvilke situationer skaber pres for dig?</p><p>Bedøm hver fra 1 (intet pres) til 10 (ekstremt pres):</p><ul><li>Spiller mod stærke modstandere: ___/10</li><li>Vigtige turneringskampe: ___/10</li><li>Uafgjort resultat, sidste skud: ___/10</li><li>Efter at have lavet en fejl: ___/10</li><li>Når holdkammerater ser på: ___/10</li><li>Når jeg spiller dårligt: ___/10</li><li>Andet: _________________________ ___/10</li></ul><p><strong>For din højest vurderede trigger:</strong></p><p>Hvilke fysiske fornemmelser bemærker du?</p><hr><p>Hvilke tanker dukker op?</p><hr><p>Hvilken teknik vil du bruge?</p><ul><li>[ ] 3-Åndedrætsnulstilling</li><li>[ ] Rutine før optagelse</li><li>[ ] Omformulering</li><li>[ ] Andet: _____________________</li></ul><hr><h2 id="øvelse-6-øvelse-i-tilstandsskift" tabindex="-1">Øvelse 6: Øvelse i tilstandsskift <a class="header-anchor" href="#øvelse-6-øvelse-i-tilstandsskift" aria-label="Permalink to &quot;Øvelse 6: Øvelse i tilstandsskift&quot;">​</a></h2><h3 id="planlægning-vs-udførelse" tabindex="-1">Planlægning vs. udførelse <a class="header-anchor" href="#planlægning-vs-udførelse" aria-label="Permalink to &quot;Planlægning vs. udførelse&quot;">​</a></h3><p><strong>Øv dig i at skifte:</strong></p><p><strong>Planlægningsfase (før optagelse):</strong></p><ul><li>Hvad skal jeg analysere?</li><li>Hvad er min strategi?</li><li>Hvilket skud vil jeg vælge?</li></ul><p><strong>Udførelsesfase (under optagelse):</strong></p><ul><li>Ryd op i dit sind</li><li>Stol på din krop</li><li>Lad det ske</li></ul><p><strong>Øvelse:</strong></p><p>Tag 5 øvelsesskud. For hvert:</p><ol><li>Brug 10 sekunder i planlægningstilstand (analyser, beslut)</li><li>Tag 3 åndedrag for at skifte tilstand</li><li>Udfør i flowtilstand (ingen tænkning)</li></ol><p><strong>Afspejling:</strong></p><ul><li>Kunne du mærke forskellen mellem tilstandene?</li><li>Var skiftet tydeligt?</li><li>Hvilken tilstand er sværest for dig?</li></ul><hr><hr><hr><h2 id="øvelse-7-ugentlig-træningsplan" tabindex="-1">Øvelse 7: Ugentlig træningsplan <a class="header-anchor" href="#øvelse-7-ugentlig-træningsplan" aria-label="Permalink to &quot;Øvelse 7: Ugentlig træningsplan&quot;">​</a></h2><h3 id="denne-uges-fokus" tabindex="-1">Denne uges fokus <a class="header-anchor" href="#denne-uges-fokus" aria-label="Permalink to &quot;Denne uges fokus&quot;">​</a></h3><p><strong>Vælg ÉN teknik at øve dig på:</strong></p><ul><li>[ ] 3-Åndedrætsnulstilling efter hver fejl</li><li>[ ] Rutine før kast ved hvert kast</li><li>[] Omformuler én Indre Kritiker-tanke per session</li><li>[ ] Skift af øvelsestilstand</li></ul><p><strong>Daglig træning:</strong></p><table tabindex="0"><thead><tr><th>Dag</th><th>Øvelsesaktivitet</th><th>Varighed</th><th>Noter</th></tr></thead><tbody><tr><td>man</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Tirs</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Ons</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>tors</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>fre</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Lørdag</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sol</td><td>________________</td><td>___min</td><td>________________</td></tr></tbody></table><hr><h2 id="øvelse-8-fremskridtssporing" tabindex="-1">Øvelse 8: Fremskridtssporing <a class="header-anchor" href="#øvelse-8-fremskridtssporing" aria-label="Permalink to &quot;Øvelse 8: Fremskridtssporing&quot;">​</a></h2><h3 id="refleksion-ved-ugens-afslutning" tabindex="-1">Refleksion ved ugens afslutning <a class="header-anchor" href="#refleksion-ved-ugens-afslutning" aria-label="Permalink to &quot;Refleksion ved ugens afslutning&quot;">​</a></h3><p><strong>Hvad har du øvet dig i denne uge?</strong></p><hr><p><strong>Hvad bemærkede du?</strong></p><hr><hr><p><strong>Hvad fungerede godt?</strong></p><hr><hr><p><strong>Hvad var udfordrende?</strong></p><hr><hr><p><strong>Hvad vil du fortsætte med i næste uge?</strong></p><hr><hr><p><strong>Hvad vil du justere?</strong></p><hr><hr><hr><h2 id="næste-trin" tabindex="-1">Næste trin <a class="header-anchor" href="#næste-trin" aria-label="Permalink to &quot;Næste trin&quot;">​</a></h2><h3 id="fortsæt-din-udvikling" tabindex="-1">Fortsæt din udvikling <a class="header-anchor" href="#fortsæt-din-udvikling" aria-label="Permalink to &quot;Fortsæt din udvikling&quot;">​</a></h3><p><strong>Ressourcer på carreau.app:</strong></p><ul><li>Målskabelon - Strukturer din langsigtede udvikling</li><li>Dagbogsskabelon - Spor daglige fremskridt</li><li>Zonen - Dyk ned i flowtilstande</li><li>Mental styrke - Avanceret preshåndtering</li></ul><p><strong>Bliv ved med at øve dig:</strong></p><ul><li>Mentale færdigheder kræver regelmæssig træning</li><li>Start småt, byg gradvist op</li><li>Spor dine fremskridt</li><li>Fejr forbedringer</li></ul><hr><p><em>Pétanque Academy - Elite Player Development</em><em>carreau.app</em></p>',113)])])}]]);export{_ as __pageData,l as default};
